import java.util.List;
import java.util.function.IntUnaryOperator;

/** A type with every kind of member { and braces in comments }. */
@SuppressWarnings({"unchecked", "rawtypes"})
public class Members {
    private static final int[] TABLE = {1, 2, 3};
    private final String brace = "}{ not a block";
    private final char open = '{';
    static int counter;

    static {
        counter = TABLE.length;
    }

    {
        counter++;
    }

    // a line comment with a brace {
    public Members() {
        super();
    }

    @Deprecated
    public <T> List<T> wrap(T value) {
        return List.of(value);
    }

    private final IntUnaryOperator twice = x -> {
        return x * 2;
    };

    static class Inner {
        int size() { return 1; }
    }

    enum Mode { FAST, SLOW }

    record Pair(int a, int b) { }

    interface Shape {
        default double area() { return 0; }
    }
}

